-- 首都まわりの町づくり（t61）の持ち主の会社：国営（風の芽帝国空軍・風の芽帝国海軍。株なし）と、AIの会社（新聞社24社・紺野観光・玖珠リゾート開発・中小企業8社。上場）
-- もうある会社は作らない（何度流しても同じ）。会社の名前・説明だけで、お金の数は入れない
do $$
declare adm uuid := nullif(btrim(split_part((select value from app_settings where key = 'admins'), ',', 1)), '')::uuid; r record; n int := 0;
begin
  if adm is null or not exists (select 1 from profiles where id = adm) then raise exception '管理者が見つかりません'; end if;
  for r in select * from (values
      ('風の芽帝国空軍', '国の空軍（国営・株なし）。若宮基地（滑走路2本・格納庫・管制塔など）と関連施設を持つ'),
      ('風の芽帝国海軍', '国の海軍（国営・株なし）。藍幡基地（岸壁・乾ドック・海軍工廠など）と関連施設を持つ')) v(nm, ds) loop
    if exists (select 1 from companies where lower(name) = lower(r.nm) and status not in ('rejected', 'closed', 'bankrupt')) then continue; end if;
    insert into companies(cid, owner, name, kind, form, description, status, balance, created_at, decided_at, industries, desk_on, listed, official, ai)
    values (_new_ccode(), adm, r.nm, '一般', '国営', r.ds, 'active', 0, _now(), _now(), '{97}', false, false, true, false);
    n := n + 1;
  end loop;
  if (select count(*) from companies where official and not ai and not listed and status = 'active' and name in ('風の芽帝国空軍', '風の芽帝国海軍')) <> 2 then
    raise exception '国営の会社（空軍・海軍）を作れませんでした（同じ名前の会社があるかもしれません）';
  end if;
  raise warning '国営の会社：新しく % 社', n;
end $$;

